describe('provider thinking signatures', () => {
  it('accepts an empty OpenCode signature', async () => {
    const provider = new FauxProvider();
    provider.thinking({ signature: '' });
    const response = await complete(provider);
    expect(response.stopReason).toBe('stop');
  });

  it('retains the strict Anthropic guard', async () => {
    const provider = new FauxProvider({ anthropic: true });
    provider.thinking({ signature: '' });
    await expect(complete(provider)).rejects.toThrow(MissingSignature);
  });

  it('accepts a non-empty Anthropic signature', async () => {
    const provider = new FauxProvider({ anthropic: true });
    provider.thinking({ signature: 'test-signature' });
    const response = await complete(provider);
    expect(response.stopReason).toBe('stop');
  });

  // Offline mock-provider regression cases.
  // No live API keys or network requests.
});

